const row = items[0]?.json ?? {};

const configured = (value) => !!value && !String(value).includes('__PENDIENTE__');
const safe = (value, fallback = '') => String(value ?? fallback).trim();
const asInt = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};
const asObject = (value) => {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(String(value || '{}'));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (_error) {
    return {};
  }
};
const normalizePhone = (value) => {
  const raw = safe(value);
  if (!raw) return '';

  const compact = raw.replace(/\s+/g, '');
  if (compact.startsWith('+')) {
    const digits = compact.slice(1).replace(/\D/g, '');
    return digits ? `+${digits}` : '';
  }

  const digits = compact.replace(/\D/g, '');
  return digits ? `+${digits}` : '';
};

const leadId = row.lead_id;
const shouldCreateClickup = Boolean(row.should_create_clickup);
const existingClickupTaskId = safe(row.existing_clickup_task_id);
const existingClickupTaskUrl = safe(row.existing_clickup_task_url);
const clickupOperationKey = safe(row.clickup_operation_key, `clickup-task:lead:${leadId}`);
if (!leadId) {
  throw new Error('CRM - ClickUp Sync Lead requiere lead_id');
}

const listId = $env.CLICKUP_LIST_ID;
if (!configured(listId)) {
  throw new Error('CLICKUP_LIST_ID no esta configurado');
}

const whatsappName = safe(row.whatsapp_name, 'Sin Nombre');
const service = safe(row.service, 'Sin Servicio');
const city = safe(row.city, 'Sin Ciudad');
const requirement = safe(row.requirement, 'Sin requerimiento informado');
const phoneNumber = safe(row.phone_number);
const clickupPhoneNumber = normalizePhone(phoneNumber);
const channel = safe(row.channel, 'whatsapp');
const sourceNumberId = safe(row.source_number_id);
const fullConversation = safe(row.full_conversation);
const advisorOutput = asObject(row.advisor_output_payload);
const diagnostic = asObject(advisorOutput.diagnostic_datos);
const qualification = asObject(row.qualification_context);
const qualificationLabels = {
  modality: 'Modalidad',
  quantity: 'Cantidad',
  measurements: 'Medidas',
  use_case: 'Uso/proyecto',
  terrain: 'Terreno',
  truck_access: 'Acceso camion',
  debris_removal: 'Retiro escombros',
  urgency: 'Urgencia',
  desired_date: 'Fecha deseada',
  photos: 'Fotos',
  customer_type: 'Tipo cliente',
  company: 'Empresa',
  company_rut: 'RUT empresa',
  purchase_order: 'Orden de compra',
  invoice_required: 'Requiere factura',
  address: 'Direccion',
  access_restrictions: 'Restricciones de acceso',
};
const formatQualificationValue = (value) => typeof value === 'boolean' ? (value ? 'Si' : 'No') : safe(value);
const qualificationLines = Object.entries(qualificationLabels)
  .filter(([key]) => qualification[key] !== undefined && qualification[key] !== null && qualification[key] !== '')
  .map(([key, label]) => `${label}: ${formatQualificationValue(qualification[key])}`);
const advisorLines = [
  advisorOutput.lead_class ? 'Clasificacion: ' + advisorOutput.lead_class : null,
  advisorOutput.customer_type ? 'Tipo cliente: ' + advisorOutput.customer_type : null,
  advisorOutput.modality ? 'Modalidad: ' + advisorOutput.modality : null,
  advisorOutput.objection_detected && advisorOutput.objection_detected !== 'none' ? 'Objecion: ' + advisorOutput.objection_detected : null,
  advisorOutput.escalation_area && advisorOutput.escalation_area !== 'none' ? 'Escalamiento: ' + advisorOutput.escalation_area : null,
  advisorOutput.next_best_action ? 'Siguiente accion: ' + advisorOutput.next_best_action : null,
  advisorOutput.executive_summary ? 'Resumen AI: ' + advisorOutput.executive_summary : null,
  diagnostic.pain ? 'Dolor: ' + diagnostic.pain : null,
  diagnostic.scope ? 'Alcance: ' + diagnostic.scope : null,
  diagnostic.timing ? 'Tiempo: ' + diagnostic.timing : null,
  diagnostic.obstacle ? 'Obstaculo: ' + diagnostic.obstacle : null,
  ...qualificationLines,
].filter(Boolean);

const taskName = `${whatsappName} - ${service} - ${city}`;
const description = [
  'Resumen del lead',
  '',
  `Telefono: ${clickupPhoneNumber || phoneNumber || 'No informado'}`,
  `Canal: ${channel || 'whatsapp'}`,
  `Ciudad: ${city}`,
  `Servicio: ${service}`,
  `Requerimiento: ${requirement}`,
  sourceNumberId ? `Numero de Ingreso: ${sourceNumberId}` : null,
  advisorLines.length ? '' : null,
  advisorLines.length ? 'Diagnostico comercial AI' : null,
  ...advisorLines,
].filter(Boolean).join('\n');

const customFields = [];
const pushCustomField = (fieldId, value) => {
  if (!configured(fieldId)) return;
  if (value === undefined || value === null || value === '') return;
  customFields.push({ id: fieldId, value });
};

pushCustomField($env.CLICKUP_CF_WHATSAPP_NAME_ID, whatsappName);
pushCustomField($env.CLICKUP_CF_PHONE_ID, clickupPhoneNumber || phoneNumber);
pushCustomField($env.CLICKUP_CF_SERVICE_ID, service);
pushCustomField($env.CLICKUP_CF_CITY_ID, city);
pushCustomField($env.CLICKUP_CF_REQUIREMENT_ID, requirement);
pushCustomField($env.CLICKUP_CF_INTERNAL_LEAD_ID, String(leadId));
pushCustomField($env.CLICKUP_CF_SOURCE_NUMBER_ID, sourceNumberId || null);
if (configured($env.CLICKUP_CF_CHANNEL_ID) && configured($env.CLICKUP_CF_CHANNEL_OPTION_WHATSAPP_ID)) {
  customFields.push({
    id: $env.CLICKUP_CF_CHANNEL_ID,
    value: $env.CLICKUP_CF_CHANNEL_OPTION_WHATSAPP_ID,
  });
}

const assigneeId = asInt(row.clickup_user_id);
const taskPayload = {
  name: taskName,
  description,
  notify_all: false,
  assignees: assigneeId ? [assigneeId] : [],
  custom_fields: customFields,
};

const commentText = [
  advisorLines.length ? 'Resumen Comercial AI\n\n' + advisorLines.join('\n') : '',
  fullConversation ? 'Conversación Completa Cliente\n\n' + fullConversation : '',
].filter(Boolean).join('\n\n');

return [
  {
    json: {
      lead_id: leadId,
      should_create_clickup: shouldCreateClickup,
      existing_clickup_task_id: existingClickupTaskId || null,
      existing_clickup_task_url: existingClickupTaskUrl || null,
      clickup_operation_key: clickupOperationKey,
      task_name: taskName,
      task_description: description,
      attachments_json: row.attachments_json || [],
      clickup_task_url: `https://api.clickup.com/api/v2/list/${listId}/task`,
      clickup_task_payload: taskPayload,
      comment_text: commentText,
      comment_enabled: Boolean(commentText),
    },
  },
];

const explicitlySafeRetryStatusCodes = new Set([425, 429]);
const maxAttempts = Number($env.EXTERNAL_HTTP_MAX_ATTEMPTS || 4);
const baseDelayMs = Number($env.EXTERNAL_HTTP_RETRY_BASE_MS || 1000);
const maxDelayMs = Number($env.EXTERNAL_HTTP_RETRY_MAX_MS || 10000);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const retryDelay = (attempt) => Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt - 1));
const normalizeBody = (value) => {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch (_error) { return { raw: value }; }
  }
  return value || {};
};
const outcome = (statusCode, body, headers, attempt, operationOutcome, extra = {}) => ({
  statusCode, body: normalizeBody(body), headers: headers || {}, retry_attempts: attempt,
  retry_exhausted: Boolean(extra.retry_exhausted), retry_last_error: extra.retry_last_error || null,
  operation_outcome: operationOutcome,
  reconciliation_required: operationOutcome === 'unknown',
  retry_safe: Boolean(extra.retry_safe),
  idempotent_replay: Boolean(extra.idempotent_replay),
  idempotency_in_progress: Boolean(extra.idempotency_in_progress),
});

const row = items[0]?.json ?? {};
const shouldCreateClickup = Boolean(row.should_create_clickup);
const existingTaskId = String(row.existing_clickup_task_id || '').trim();
const operationStatus = String(row.clickup_operation_status || '').trim();
if (!shouldCreateClickup) {
  if (existingTaskId) return [{ json: outcome(200, { id: existingTaskId, url: row.existing_clickup_task_url || null }, {}, 0, 'succeeded', { idempotent_replay: true }) }];
  if (operationStatus === 'unknown' || row.clickup_reconciliation_required) {
    return [{ json: outcome(0, { message: row.clickup_reconciliation_reason || 'Manual reconciliation required' }, {}, 0, 'unknown') }];
  }
  if (operationStatus === 'failed') {
    return [{ json: outcome(0, { message: 'ClickUp operation failed and is not safe to retry automatically' }, {}, 0, 'failed') }];
  }
  return [{ json: outcome(202, {}, {}, 0, 'in_progress', { idempotency_in_progress: true }) }];
}
const url = String(row.clickup_task_url || '').trim();
const body = row.clickup_task_payload;
if (!url) throw new Error('Create ClickUp Task requiere clickup_task_url');
if (!body) throw new Error('Create ClickUp Task requiere clickup_task_payload');

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    const response = await helpers.httpRequest({
      method: 'POST', url,
      headers: { Authorization: $env.CLICKUP_API_TOKEN, 'Content-Type': 'application/json' },
      body, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    const statusCode = Number(response.statusCode || 0);
    if (statusCode >= 200 && statusCode < 300) {
      return [{ json: outcome(statusCode, response.body, response.headers, attempt, 'succeeded') }];
    }
    if (explicitlySafeRetryStatusCodes.has(statusCode)) {
      if (attempt < maxAttempts) { await sleep(retryDelay(attempt)); continue; }
      return [{ json: outcome(statusCode, response.body, response.headers, attempt, 'failed', { retry_exhausted: true, retry_safe: true }) }];
    }
    // 408 and every 5xx are ambiguous for a non-idempotent POST: ClickUp may
    // have created the task before the response was lost. Never POST again.
    if (statusCode === 408 || statusCode >= 500 || statusCode === 0) {
      return [{ json: outcome(statusCode, response.body, response.headers, attempt, 'unknown') }];
    }
    return [{ json: outcome(statusCode, response.body, response.headers, attempt, 'failed') }];
  } catch (error) {
    // A transport timeout/error does not prove the POST was rejected.
    return [{ json: outcome(0, { message: error.message }, {}, attempt, 'unknown', { retry_last_error: error.message }) }];
  }
}
return [{ json: outcome(0, { message: 'Unexpected ClickUp execution state' }, {}, maxAttempts, 'unknown') }];

const row = items[0]?.json ?? {};

const statusCode = Number(row.statusCode_2 || row.statusCode || 0);
const responseBody = row.body_2 || row.body || {};
const retryAttempts = Number(row.retry_attempts_2 || row.retry_attempts || 1);
const retryExhausted = Boolean(row.retry_exhausted_2 || row.retry_exhausted || false);
const retryLastError = row.retry_last_error_2 || row.retry_last_error || null;
const idempotentReplay = Boolean(row.idempotent_replay_2 || row.idempotent_replay || false);
const operationOutcome = String(row.operation_outcome_2 || row.operation_outcome || '').trim() || 'failed';
const reconciliationRequired = Boolean(row.reconciliation_required_2 || row.reconciliation_required || operationOutcome === 'unknown');
const retrySafe = Boolean(row.retry_safe_2 || row.retry_safe || false);
const idempotencyInProgress = Boolean(row.idempotency_in_progress_2 || row.idempotency_in_progress || false);
const isSuccess = statusCode >= 200 && statusCode < 300 && !!responseBody?.id;
const taskId = isSuccess ? String(responseBody.id) : null;
const taskUrl = isSuccess ? String(responseBody.url || `https://app.clickup.com/t/${responseBody.id}`) : null;

return [
  {
    json: {
      lead_id: row.lead_id_1 || row.lead_id,
      clickup_operation_key: row.clickup_operation_key_1 || row.clickup_operation_key || null,
      idempotent_replay: idempotentReplay,
      idempotency_in_progress: idempotencyInProgress,
      clickup_task_id: taskId,
      clickup_task_url: taskUrl,
      is_success: isSuccess,
      event_name: 'clickup_task_sync',
      result: isSuccess ? 'success' : operationOutcome === 'unknown' ? 'unknown' : 'error',
      operation_outcome: isSuccess ? 'succeeded' : operationOutcome,
      reconciliation_required: reconciliationRequired,
      retry_safe: retrySafe,
      comment_enabled: Boolean(row.comment_enabled_1 || row.comment_enabled),
      comment_text: row.comment_text_1 || row.comment_text || '',
      after_payload_json: JSON.stringify({
        status_code: statusCode,
        response_body: responseBody,
        retry_attempts: retryAttempts,
        retry_exhausted: retryExhausted,
        operation_outcome: isSuccess ? 'succeeded' : operationOutcome,
        reconciliation_required: reconciliationRequired,
        retry_safe: retrySafe,
        retry_last_error: retryLastError,
      }),
      metadata_json: JSON.stringify({
        task_name: row.task_name_1 || row.task_name || null,
        attachments_count: Array.isArray(row.attachments_json_1) ? row.attachments_json_1.length : 0,
        provider: 'clickup',
        retry_attempts: retryAttempts,
        retry_exhausted: retryExhausted,
        operation_outcome: isSuccess ? 'succeeded' : operationOutcome,
        reconciliation_required: reconciliationRequired,
        retry_safe: retrySafe,
      }),
    },
  },
];

const row = items[0]?.json ?? {};
const clickupTaskId = String(row.clickup_task_id || '').trim();
const commentText = String(row.comment_text || '').trim();
const shouldComment = Boolean(row.comment_enabled) && !Boolean(row.idempotent_replay) && clickupTaskId && commentText;
let conversationCommentStatus = 'skipped';
let conversationCommentStatusCode = null;
let conversationCommentId = null;
let conversationCommentError = null;
let conversationCommentAttempts = 0;
let conversationCommentOutcome = 'skipped';
let conversationCommentReconciliationRequired = false;
let conversationCommentRetrySafe = false;
if (shouldComment) {
  conversationCommentAttempts = 1;
  try {
    const response = await helpers.httpRequest({
      method: 'POST',
      url: 'https://api.clickup.com/api/v2/task/' + encodeURIComponent(clickupTaskId) + '/comment',
      headers: { Authorization: $env.CLICKUP_API_TOKEN, 'Content-Type': 'application/json' },
      body: { comment_text: commentText, notify_all: false },
      json: true, returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    conversationCommentStatusCode = Number(response.statusCode || 0);
    const responseBody = response.body || {};
    conversationCommentId = responseBody?.id || responseBody?.comment?.id || null;
    if (conversationCommentStatusCode >= 200 && conversationCommentStatusCode < 300) {
      conversationCommentStatus = 'created';
      conversationCommentOutcome = 'succeeded';
    } else if (conversationCommentStatusCode === 408 || conversationCommentStatusCode >= 500 || conversationCommentStatusCode === 0) {
      conversationCommentStatus = 'unknown';
      conversationCommentOutcome = 'unknown';
      conversationCommentReconciliationRequired = true;
      conversationCommentError = JSON.stringify(responseBody);
    } else {
      conversationCommentStatus = 'error';
      conversationCommentOutcome = 'failed';
      conversationCommentRetrySafe = [425, 429].includes(conversationCommentStatusCode);
      conversationCommentError = JSON.stringify(responseBody);
    }
  } catch (error) {
    // The provider may have created the comment before the transport failed.
    conversationCommentStatus = 'unknown';
    conversationCommentOutcome = 'unknown';
    conversationCommentReconciliationRequired = true;
    conversationCommentError = error.message;
  }
}
return [{ json: {
  ...row,
  conversation_comment_status: conversationCommentStatus,
  conversation_comment_status_code: conversationCommentStatusCode,
  conversation_comment_id: conversationCommentId,
  conversation_comment_error: conversationCommentError,
  conversation_comment_attempts: conversationCommentAttempts,
  conversation_comment_retry_exhausted: false,
  conversation_comment_outcome: conversationCommentOutcome,
  conversation_comment_reconciliation_required: conversationCommentReconciliationRequired,
  conversation_comment_retry_safe: conversationCommentRetrySafe,
} }];

const row = items[0]?.json ?? {};
const taskId = String(row.clickup_task_id || '').trim() || null;
const operationOutcome = String(row.operation_outcome || '').trim()
  || (taskId ? 'succeeded' : row.idempotency_in_progress ? 'in_progress' : 'skipped');
return [{
  json: {
    lead_id: row.lead_id || null,
    clickup_task_id: taskId,
    clickup_task_url: row.clickup_task_url || null,
    audit_id: row.audit_id || null,
    operation_outcome: operationOutcome,
    reconciliation_required: Boolean(row.reconciliation_required || operationOutcome === 'unknown'),
    retry_safe: Boolean(row.retry_safe),
    idempotency_in_progress: Boolean(row.idempotency_in_progress || operationOutcome === 'in_progress'),
    terminal_result_emitted: true,
    conversation_comment_status: row.conversation_comment_status || 'skipped',
    conversation_comment_id: row.conversation_comment_id || null,
    conversation_comment_outcome: row.conversation_comment_outcome || 'skipped',
    conversation_comment_reconciliation_required: Boolean(row.conversation_comment_reconciliation_required),
  },
}];
